effect.shader:
vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy
void main ()
{
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
vec2 image_size = inputImg.size;
vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
vec4 fragColor;
vec2 uv = acScreenNorm.st;
uv = uv * 2.0 - 1.0;
uv.x *= iResolution.x / iResolution.y;
float nearPlane = 1.0;
float rotX = ROT.y * 0.01;
float rotY = ROT.x * 0.01;
float rotZ = ROT.z * 0.01;
vec3 rayOrigin = vec3(0.0, 0.0, rotZ);
vec3 rayDir = normalize(vec3(uv, -nearPlane));
float cosX = cos(rotX);
float sinX = sin(rotX);
mat3 rotXMat = mat3(
1.0,   0.0,    0.0,
0.0,  cosX,  -sinX,
0.0,  sinX,   cosX
);
float cosY = cos(rotY);
float sinY = sin(rotY);
mat3 rotYMat = mat3(
cosY, 0.0, sinY,
0.0,  1.0, 0.0,
-sinY, 0.0, cosY
);
rayDir = rotYMat * rotXMat * rayDir;
float t = -rayOrigin.z / rayDir.z;
vec3 hitPos = rayOrigin + rayDir * t;
vec2 texUV = hitPos.xy;
texUV.x /= (iResolution.x / iResolution.y);
texUV = texUV * 0.5 + 0.5;
float flipX = mod(floor(rotX / 3.14159265), 2.0);
float flipY = mod(floor(rotY / 3.14159265), 2.0);
if (MIRX > 0.1) {
texUV.x = 1.0 - texUV.x;
}
if (MIRY > 0.1) {
texUV.y = 1.0 - texUV.y;
}
vec4 color = texture2DCv(inputImg.texture, texUV);
if (texUV.x < 0.0 || texUV.x > 1.0 || texUV.y < 0.0 || texUV.y > 1.0) {
color = vec4(0.0);
}
fragColor = color;
gl_FragColor = fragColor * color.a;
}
